const existing = $input.first().json;
const gmailProfile = $('Get Gmail Profile').first().json;
const primaryUser = $('Get Primary User').first().json[0];

const account = Array.isArray(existing) && existing[0] ? existing[0] : null;
// First run: only look back 24h, to avoid importing years of mail on first connect.
const sinceTimestamp = account?.last_synced_at
  ? Math.floor(new Date(account.last_synced_at).getTime() / 1000)
  : Math.floor(Date.now() / 1000) - 86400;

return [{
  json: {
    user_id: primaryUser.id,
    email_address: gmailProfile.emailAddress,
    since_timestamp: sinceTimestamp
  }
}];

const msg = $input.first().json;
const accountRow = $('Upsert Email Account').first().json;
const account = Array.isArray(accountRow) ? accountRow[0] : accountRow;
const userId = $('Determine Sync Window').first().json.user_id;

function getHeader(headers, name) {
  const h = (headers || []).find(h => h.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : null;
}

function findBody(payload, mimeType) {
  if (payload.mimeType === mimeType && payload.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf-8');
  }
  if (payload.parts) {
    for (const part of payload.parts) {
      const result = findBody(part, mimeType);
      if (result) return result;
    }
  }
  return null;
}

function findAttachments(payload, list = []) {
  if (payload.filename && payload.filename.length > 0 && payload.body?.attachmentId) {
    list.push({
      filename: payload.filename,
      mime_type: payload.mimeType,
      attachment_id: payload.body.attachmentId,
      size_bytes: payload.body.size || null
    });
  }
  if (payload.parts) {
    for (const part of payload.parts) {
      findAttachments(part, list);
    }
  }
  return list;
}

const headers = msg.payload?.headers || [];
const bodyText = findBody(msg.payload, 'text/plain') || '';
const bodyHtml = findBody(msg.payload, 'text/html') || '';
const attachments = findAttachments(msg.payload);
const fromHeader = getHeader(headers, 'From') || '';
const toHeader = getHeader(headers, 'To') || '';

return [{
  json: {
    user_id: userId,
    email_account_id: account.id,
    gmail_message_id: msg.id,
    gmail_thread_id: msg.threadId,
    rfc_message_id: getHeader(headers, 'Message-ID'),
    from_address: fromHeader.match(/<(.+)>/)?.[1] || fromHeader,
    from_name: fromHeader.replace(/<.*>/, '').trim(),
    to_addresses: toHeader.split(',').map(s => s.trim()).filter(Boolean),
    subject: getHeader(headers, 'Subject') || '(no subject)',
    body_text: bodyText,
    body_html: bodyHtml,
    snippet: msg.snippet || '',
    received_at: new Date(parseInt(msg.internalDate, 10)).toISOString(),
    has_attachments: attachments.length > 0,
    attachments
  }
}];

const insertedRows = $input.first().json;
const email = Array.isArray(insertedRows) ? insertedRows[0] : insertedRows;
const parsed = $('Parse Email').first().json;
const attachments = parsed.attachments || [];
if (!email || attachments.length === 0) return [];
return attachments.map(a => ({
  json: {
    email_id: email.id,
    user_id: parsed.user_id,
    filename: a.filename,
    mime_type: a.mime_type,
    size_bytes: a.size_bytes,
    gmail_attachment_id: a.attachment_id
  }
}));

const insertedRows = $input.first().json;
const email = Array.isArray(insertedRows) ? insertedRows[0] : insertedRows;
return [{ json: { email_id: email.id } }];
